1	using System.Data;
2	using System.Diagnostics;
3	using System.Reflection;
4	using Asp.Versioning;
5	using DbUp;
6	using DbUp.Sqlite;
7	using Kanban.AntiCorruption.Adapters;
8	using Kanban.Api.Auth;
9	using Kanban.Api.ErrorHandling;
10	using Kanban.Api.Health;
11	using Kanban.Api.Options;
12	using Kanban.Business.Interfaces;
13	using Kanban.Business.Services;
14	using Kanban.Api.Endpoints;
15	using Kanban.DataAccess;
16	using Kanban.DataAccess.Interfaces;
17	using Kanban.DataAccess.Repositories;
18	using Microsoft.AspNetCore.Authentication;
19	using Microsoft.AspNetCore.Authentication.Cookies;
20	using Microsoft.AspNetCore.Authentication.Google;
21	using Microsoft.AspNetCore.Authorization;
22	using Microsoft.AspNetCore.Diagnostics.HealthChecks;
23	using Microsoft.AspNetCore.HttpOverrides;
24	using Microsoft.AspNetCore.RateLimiting;
25	using Microsoft.Data.Sqlite;
26	using Microsoft.Extensions.Options;
27	using NetEscapades.AspNetCore.SecurityHeaders;
28	using Scalar.AspNetCore;
29	using CorsOptions = Kanban.Api.Options.CorsOptions;
30	
31	var builder = WebApplication.CreateBuilder(args);
32	
33	// ── Options — fail at boot if configuration is missing ────────────────────────
34	
35	builder.Services.AddOptions<GoogleAuthOptions>()
36	    .Bind(builder.Configuration.GetSection(GoogleAuthOptions.SectionName))
37	    .ValidateDataAnnotations()
38	    .ValidateOnStart();
39	
40	builder.Services.AddOptions<SeedOptions>()
41	    .Bind(builder.Configuration.GetSection(SeedOptions.SectionName))
42	    .ValidateDataAnnotations()
43	    .ValidateOnStart();
44	
45	builder.Services.AddOptions<CorsOptions>()
46	    .Bind(builder.Configuration.GetSection(CorsOptions.SectionName))
47	    .ValidateDataAnnotations()
48	    .ValidateOnStart();
49	
50	builder.Services.AddOptions<ConnectionStringOptions>()
51	    .Bind(builder.Configuration.GetSection(ConnectionStringOptions.SectionName))
52	    .ValidateDataAnnotations()
53	    .ValidateOnStart();
54	
55	// ── Database ──────────────────────────────────────────────────────────────────
56	
57	DapperConfiguration.RegisterTypeHandlers();
58	
59	var connectionString = builder.Configuration.GetConnectionString("Kanban")
60	    ?? throw new InvalidOperationException("ConnectionStrings:Kanban is required.");
61	
62	builder.Services.AddScoped<IDbConnection>(_ =>
63	{
64	    var conn = new SqliteConnection(connectionString);
65	    conn.Open();
66	    return conn;
67	});
68	
69	// ── Exception Handling ────────────────────────────────────────────────────────
70	
71	builder.Services.AddProblemDetails(options =>
72	{
73	    options.CustomizeProblemDetails = ctx =>
74	    {
75	        ctx.ProblemDetails.Extensions["traceId"] = Activity.Current?.Id;
76	        if (ctx.HttpContext.Response.StatusCode == StatusCodes.Status403Forbidden
77	            && !ctx.ProblemDetails.Extensions.ContainsKey("code"))
78	        {
79	            ctx.ProblemDetails.Title = "You are not registered to use this application.";
80	            ctx.ProblemDetails.Extensions["code"] = "user.not_registered";
81	        }
82	    };
83	});
84	builder.Services.AddExceptionHandler<DomainExceptionHandler>();
85	builder.Services.AddExceptionHandler<InfrastructureExceptionHandler>();
86	builder.Services.AddExceptionHandler<FallbackExceptionHandler>();
87	
88	// ── CORS ──────────────────────────────────────────────────────────────────────
89	
90	builder.Services.AddCors(options =>
91	    options.AddPolicy("KanbanWebApp", policy =>
92	        policy
93	            .WithOrigins(
94	                builder.Configuration
95	                    .GetSection("Cors:AllowedOrigins")
96	                    .Get<string[]>() ?? [])
97	            .WithMethods("GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS")
98	            .AllowAnyHeader()
99	            .WithExposedHeaders("X-Correlation-Id", "api-supported-versions")));
100	
101	// ── Authentication & Authorization ───────────────────────────────────────────
102	
103	builder.Services.AddScoped<ICurrentUserService, CurrentUserService>();
104	builder.Services.AddScoped<IAuthService, AuthService>();
105	builder.Services.AddScoped<GoogleIdentityAdapter>();
106	builder.Services.AddScoped<IUserRepository, UserRepository>();
107	builder.Services.AddScoped<IAuthEventRepository, AuthEventRepository>();
108	builder.Services.AddScoped<IInvitationRepository, InvitationRepository>();
109	builder.Services.AddHttpContextAccessor();
110	builder.Services.AddScoped<IAuthorizationHandler, RegisteredUserHandler>();
111	
112	builder.Services.AddAuthentication(options =>
113	    {
114	        options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
115	        options.DefaultChallengeScheme = GoogleDefaults.AuthenticationScheme;
116	    })
117	    .AddCookie(options =>
118	    {
119	        options.LoginPath = "/api/v1/auth/signin";
120	        options.Events.OnRedirectToLogin = ctx =>
121	        {
122	            ctx.Response.StatusCode = StatusCodes.Status401Unauthorized;
123	            return Task.CompletedTask;
124	        };
125	        options.Events.OnRedirectToAccessDenied = ctx =>
126	        {
127	            ctx.Response.StatusCode = StatusCodes.Status403Forbidden;
128	            return Task.CompletedTask;
129	        };
130	    })
131	    .AddGoogle(options =>
132	    {
133	        var googleOpts = builder.Configuration
134	            .GetSection(GoogleAuthOptions.SectionName)
135	            .Get<GoogleAuthOptions>()!;
136	        options.ClientId = googleOpts.ClientId;
137	        options.ClientSecret = googleOpts.ClientSecret;
138	        options.Events.OnTicketReceived = async ctx =>
139	        {
140	            var adapter = ctx.HttpContext.RequestServices
141	                .GetRequiredService<GoogleIdentityAdapter>();
142	            var authService = ctx.HttpContext.RequestServices
143	                .GetRequiredService<IAuthService>();
144	
145	            if (ctx.Principal is not null)
146	            {
147	                var identity = adapter.Extract(ctx.Principal);
148	                var claimsIdentity = ctx.Principal.Identity as System.Security.Claims.ClaimsIdentity;
149	                if (claimsIdentity is not null)
150	                {
151	                    await authService.HandleSignInAsync(
152	                        identity.Sub,
153	                        identity.Email,
154	                        claimsIdentity,
155	                        ctx.HttpContext.RequestAborted);
156	                }
157	            }
158	        };
159	    });
160	
161	builder.Services.AddAuthorizationBuilder()
162	    .AddPolicy("RegisteredUser", policy => policy
163	        .RequireAuthenticatedUser()
164	        .AddRequirements(new RegisteredUserRequirement()))
165	    .AddPolicy("Admin", policy => policy
166	        .RequireAuthenticatedUser()
167	        .RequireClaim("system_role", "admin"));
168	
169	// ── API Versioning ────────────────────────────────────────────────────────────
170	
171	builder.Services.AddApiVersioning(options =>
172	{
173	    options.DefaultApiVersion = new ApiVersion(1, 0);
174	    options.AssumeDefaultVersionWhenUnspecified = true;
175	    options.ReportApiVersions = true;
176	});
177	
178	// ── OpenAPI — development only ────────────────────────────────────────────────
179	
180	if (builder.Environment.IsDevelopment())
181	    builder.Services.AddOpenApi();
182	
183	// ── Health Checks ─────────────────────────────────────────────────────────────
184	
185	builder.Services.AddHealthChecks()
186	    .AddCheck("self", () => Microsoft.Extensions.Diagnostics.HealthChecks.HealthCheckResult.Healthy(), tags: ["live"])
187	    .AddCheck<DatabaseHealthCheck>("database", tags: ["ready"]);
188	
189	// ── Rate Limiting ─────────────────────────────────────────────────────────────
190	
191	builder.Services.AddRateLimiter(opts =>
192	{
193	    opts.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
194	    opts.OnRejected = async (ctx, _) =>
195	    {
196	        ctx.HttpContext.Response.Headers.RetryAfter = "60";
197	        await Results.Problem(
198	                title: "Too many requests",
199	                statusCode: StatusCodes.Status429TooManyRequests,
200	                detail: "Please retry after the Retry-After interval.")
201	            .ExecuteAsync(ctx.HttpContext);
202	    };
203	
204	    opts.AddFixedWindowLimiter("anonymous", o =>
205	    {
206	        o.PermitLimit = 10;
207	        o.Window = TimeSpan.FromMinutes(1);
208	    });
209	
210	    opts.AddSlidingWindowLimiter("authenticated", o =>
211	    {
212	        o.PermitLimit = 100;
213	        o.Window = TimeSpan.FromMinutes(1);
214	        o.SegmentsPerWindow = 6;
215	    });
216	
217	    opts.AddSlidingWindowLimiter("mutating", o =>
218	    {
219	        o.PermitLimit = 30;
220	        o.Window = TimeSpan.FromMinutes(1);
221	        o.SegmentsPerWindow = 6;
222	    });
223	});
224	
225	// ── Build ─────────────────────────────────────────────────────────────────────
226	
227	var app = builder.Build();
228	
229	// ── Migrations ────────────────────────────────────────────────────────────────
230	
231	var seedOptions = app.Services.GetRequiredService<IOptions<SeedOptions>>().Value;
232	var migrationsAssembly = AppDomain.CurrentDomain.GetAssemblies()
233	    .FirstOrDefault(a => a.GetName().Name == "Kanban.Data")
234	    ?? Assembly.Load("Kanban.Data");
235	
236	var upgradeResult = DeployChanges.To
237	    .SqliteDatabase(connectionString)
