1	using System.Data;
2	using System.Security.Claims;
3	using Kanban.Business.Interfaces;
4	using Kanban.Contracts;
5	using Kanban.DataAccess.Interfaces;
6	using Kanban.Domain;
7	using Kanban.Domain.Entities;
8	using Kanban.Domain.Enums;
9	using Kanban.Domain.Events;
10	using Microsoft.Extensions.Logging;
11	using Polly;
12	using Polly.Retry;
13	
14	namespace Kanban.Business.Services;
15	
16	public sealed class AuthService : IAuthService
17	{
18	    private readonly IUserRepository _userRepository;
19	    private readonly IAuthEventRepository _authEventRepository;
20	    private readonly IDbConnection _dbConnection;
21	    private readonly ILogger<AuthService> _logger;
22	
23	    private static readonly ResiliencePipeline RetryPolicy =
24	        new ResiliencePipelineBuilder()
25	            .AddRetry(new RetryStrategyOptions
26	            {
27	                MaxRetryAttempts = 3,
28	                Delay = TimeSpan.FromMilliseconds(50),
29	                BackoffType = DelayBackoffType.Exponential,
30	                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
31	                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
32	                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
33	            })
34	            .Build();
35	
36	    public AuthService(
37	        IUserRepository userRepository,
38	        IAuthEventRepository authEventRepository,
39	        IDbConnection dbConnection,
40	        ILogger<AuthService> logger)
41	    {
42	        _userRepository = userRepository;
43	        _authEventRepository = authEventRepository;
44	        _dbConnection = dbConnection;
45	        _logger = logger;
46	    }
47	
48	    private static CurrentUserDto ToDto(User user) => new()
49	    {
50	        Id = user.Id,
51	        Email = user.Email,
52	        DisplayName = user.DisplayName,
53	        SystemRole = user.SystemRole == SystemRole.Admin ? "admin" : "standard",
54	        RegisteredAt = user.RegisteredAt,
55	        LastSignInAt = user.LastSignInAt,
56	    };
57	
58	    public async Task<CurrentUserDto?> GetCurrentUserAsync(
59	        Guid userId,
60	        CancellationToken cancellationToken = default)
61	    {
62	        Verify.That(userId).IsNotDefault();
63	        var user = await _userRepository.FindByIdAsync(userId);
64	        return user is null ? null : ToDto(user);
65	    }
66	
67	    public async Task HandleSignInAsync(
68	        string googleSub,
69	        string email,
70	        ClaimsIdentity claimsIdentity,
71	        CancellationToken cancellationToken = default)
72	    {
73	        Verify.That(googleSub).IsNotNull().IsNotEmpty();
74	        Verify.That(email).IsNotNull().IsNotEmpty();
75	        Verify.That(claimsIdentity).IsNotNull();
76	
77	        await RetryPolicy.ExecuteAsync(async ct =>
78	        {
79	            using var tx = _dbConnection.BeginTransaction();
80	            try
81	            {
82	                var user = await _userRepository.FindByGoogleSubAsync(googleSub, tx);
83	
84	                if (user is null)
85	                {
86	                    var userByEmail = await _userRepository.FindByEmailAsync(email, tx);
87	                    if (userByEmail is not null && userByEmail.GoogleSub is null)
88	                    {
89	                        await _userRepository.LinkGoogleSubAsync(userByEmail.Id, googleSub, tx);
90	                        userByEmail.LinkGoogleIdentity(googleSub);
91	                        user = userByEmail;
92	                    }
93	                }
94	
95	                if (user is not null)
96	                {
97	                    claimsIdentity.AddClaim(new Claim("user_id", user.Id.ToString()));
98	                    claimsIdentity.AddClaim(new Claim("system_role",
99	                        user.SystemRole == SystemRole.Admin ? "admin" : "standard"));
100	
101	                    var signedInAt = DateTimeOffset.UtcNow;
102	                    await _userRepository.UpdateLastSignInAsync(user.Id, signedInAt, tx);
103	
104	                    var authEvent = new AuthEvent(
105	                        Id: Guid.NewGuid(),
106	                        OccurredAt: signedInAt,
107	                        EventType: AuthEventType.SignIn,
108	                        UserId: user.Id,
109	                        Outcome: "success");
110	                    await _authEventRepository.RecordAsync(authEvent, tx);
111	
112	                    _logger.LogInformation(
113	                        "User {UserId} signed in with role {SystemRole}", user.Id, user.SystemRole);
114	                }
115	                else
116	                {
117	                    var authEvent = new AuthEvent(
118	                        Id: Guid.NewGuid(),
119	                        OccurredAt: DateTimeOffset.UtcNow,
120	                        EventType: AuthEventType.SignIn,
121	                        UserId: null,
122	                        Outcome: "unregistered");
123	                    await _authEventRepository.RecordAsync(authEvent, tx);
124	
125	                    _logger.LogWarning("Unregistered Google user attempted sign-in");
126	                }
127	
128	                tx.Commit();
129	            }
130	            catch
131	            {
132	                tx.Rollback();
133	                throw;
134	            }
135	        }, cancellationToken);
136	    }
137	}
