88	public sealed class TestAuthenticationHandler(
89	    IOptionsMonitor<TestAuthHandlerOptions> options,
90	    ILoggerFactory logger,
91	    UrlEncoder encoder)
92	    : AuthenticationHandler<TestAuthHandlerOptions>(options, logger, encoder)
93	{
94	    public const string SchemeName = "Test";
95	
96	    // ConcurrentDictionary is used instead of [ThreadStatic] because async request
97	    // processing can switch threads, making thread-local storage unreliable in tests.
98	    private static readonly ConcurrentDictionary<string, ClaimsPrincipal> _users = new();
99	
100	    public static string RegisterUser(ClaimsPrincipal user)
101	    {
102	        var token = Guid.NewGuid().ToString("N");
103	        _users[token] = user;
104	        return token;
105	    }
106	
107	    protected override Task<AuthenticateResult> HandleAuthenticateAsync()
108	    {
109	        if (!Request.Headers.TryGetValue("Authorization", out var authHeader))
110	            return Task.FromResult(AuthenticateResult.NoResult());
111	
112	        var headerValue = authHeader.ToString();
113	        var prefix = $"{SchemeName} ";
114	        if (!headerValue.StartsWith(prefix, StringComparison.Ordinal))
115	            return Task.FromResult(AuthenticateResult.NoResult());
116	
117	        var token = headerValue[prefix.Length..];
118	        if (!_users.TryGetValue(token, out var user))
119	            return Task.FromResult(AuthenticateResult.NoResult());
120	
121	        var ticket = new AuthenticationTicket(user, SchemeName);
122	        return Task.FromResult(AuthenticateResult.Success(ticket));
123	    }
124	}
