import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import type { ReactNode } from 'react'

export function createQueryClientWrapper() {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: { retry: false, gcTime: 0 },
      mutations: { retry: false },
    },
  })

  function Wrapper({ children }: { children: ReactNode }) {
    return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
  }

  return { queryClient, Wrapper }
}

content.thinking:
`const { Wrapper } = createQueryClientWrapper()` - ah, they destructure `Wrapper` from the result and pass `Wrapper` (the actual React component function) to `renderHook`. They DON'T pass the whole object.

So my `InviteUserDialog.test.tsx` has the bug: I'm passing the whole `createQueryClientWrapper()` return value as the wrapper, not just the `Wrapper` component.

The fix in the test is:
```tsx
function renderDialog(open = true) {
  const { Wrapper } = createQueryClientWrapper()
  return render(
    <InviteUserDialog open={open} onDismiss={vi.fn()} />,
    { wrapper: Wrapper }
  )
}
```

This will fix the render crash issue. But then the tests will still fail for behavioral reasons (which is what we want for RED state) - the stub doesn't have the logic to disable the submit button when the email field is empty, doesn't render a redemption link on successful mutation, and doesn't handle the 409 and 422 error cases.

Test 1 might actually pass since the stub has both a Label with htmlFor and an Input with matching id, so getByLabelText should find it. That's fine - RED state doesn't require all tests to fail, just the ones testing unimplemented behavior.

Looking at the actual failures: test 1 passes, but tests 2-5 fail because the stub doesn't implement button disabling logic, the redemption link rendering, or either error message type. Four failing tests is a valid RED state, so I should update the test file to use the Wrapper properly and commit this. Updating the test file to use the wrapper correctly...

