6	namespace Kanban.Api.ErrorHandling;
7	
8	public sealed class DomainExceptionHandler(IProblemDetailsService problemDetails) : IExceptionHandler
9	{
10	    public async ValueTask<bool> TryHandleAsync(
11	        HttpContext httpContext,
12	        Exception exception,
13	        CancellationToken cancellationToken)
14	    {
15	        if (exception is not DomainException domainException)
16	            return false;
17	
18	        var statusCode = domainException switch
19	        {
20	            NotFoundException => StatusCodes.Status404NotFound,
