                tx.Commit();
                _logger.LogInformation("Invitation issued by {IssuedByUserId}", issuedByUserId);
                return (InvitationTransforms.ToResponse(invitation, token.Raw, frontendBaseUrl), true);
            }
            catch { tx.Rollback(); throw; }
        }, cancellationToken);
    }
}
