using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
try
{
    // Read invitation first (still in deferred/read mode)
    var invitation = await _invitationRepository.FindByTokenHashAsync(tokenHash, tx);

    if (invitation is null || !invitation.IsRedeemable)
        throw new NotFoundException(
            "invite.invalid",
            "This invitation is no longer valid. Please request a new one.");

    if (!invitation.EmailMatches(googleEmail))
        throw new BusinessRuleException(
            "invite.email_mismatch",
            "This invitation was issued to a different email address.");

    // Insert user before TryConsumeAsync — Microsoft.Data.Sqlite 10+ enforces FK
    // constraints by default; consumed_by_user_id must reference an existing user.
    // Concurrent writers get SQLITE_BUSY here → Polly retries → retry sees consumed
    // invitation and throws NotFoundException, producing the correct 410 response.
    var user = new User(
        id: newUserId,
        email: invitation.Email,
        displayName: displayName,
        systemRole: SystemRole.Standard,
        googleSub: googleSub,
        registeredAt: acceptedAt,
        lastSignInAt: null);

    await _userRepository.InsertAsync(user, tx);

    // Atomic consume — serialises concurrent accepts
    var consumed = await _invitationRepository.TryConsumeAsync(
        tokenHash, newUserId, acceptedAt, tx);
    if (!consumed)
        throw new NotFoundException(
            "invite.invalid",
            "This invitation is no longer valid. Please request a new one.");

    var authEvent = new AuthEvent(
        Id: Guid.NewGuid(),
        OccurredAt: acceptedAt,
        EventType: AuthEventType.InvitationAccepted,
        UserId: newUserId,
        Outcome: "success");
    await _authEventRepository.RecordAsync(authEvent, tx);

